5	/**
6	 * The owner's customer code, {@code '<REGION>-<HASH8>'}: the owner's {@link OwnerRegion region}
7	 * joined to an 8-character hash that identifies the person. HASH8 is the first 8 upper-case hex
8	 * characters of {@code SHA-256(normalizedTelephone + lastName)}, so the same person (same
9	 * normalized telephone and last name) always resolves to the same code without any sequence
10	 * number (e.g. {@code 'NSW-1A2B3C4D'}).
11	 */
12	public final class CustomerCode {
13	
14	    private static final String SEPARATOR = "-";
15	
16	    /** Number of leading hex characters of the digest kept as HASH8. */
17	    private static final int HASH_LENGTH = 8;
18	
19	    private CustomerCode() {
20	    }
21	
22	    /**
23	     * The customer code for the given {@code region} and person, hashing the person's
24	     * {@code normalizedTelephone} and {@code lastName}.
25	     */
26	    public static String of(String region, String normalizedTelephone, String lastName) {
27	        return region + SEPARATOR + hash8(orEmpty(normalizedTelephone) + orEmpty(lastName));
28	    }
29	
30	    /** The REGION segment of a customer code (the text before the first {@code '-'}). */
31	    public static String region(String customerCode) {
32	        int separator = customerCode.indexOf(SEPARATOR);
33	        return separator < 0 ? customerCode : customerCode.substring(0, separator);
34	    }
35	
36	    private static String hash8(String source) {
37	        return Sha256.hex(source).substring(0, HASH_LENGTH).toUpperCase(Locale.ROOT);
38	    }
39	
40	    private static String orEmpty(String value) {
41	        return value == null ? "" : value;
42	    }
43	}
