22	 * Maps Owner & OwnerDto using Mapstruct
23	 */
24	@Mapper(uses = PetMapper.class)
25	public interface OwnerMapper {
26	
27	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
28	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
29	    @Mapping(target = "initials", expression = "java(initials(owner))")
30	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
31	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
32	    @Mapping(target = "locality", expression = "java(locality(owner))")
33	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
34	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
35	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
36	    OwnerDto toOwnerDto(Owner owner);
37	
38	    /** The owner's stored E.164 telephone formatted for people to read (country code, space,
39	     *  national digits grouped in threes), or null when it is not a recognised E.164 number.
40	     *  See {@link OwnerTelephone#toDisplay}. */
41	    default String telephoneDisplay(Owner owner) {
42	        return OwnerTelephone.toDisplay(owner.getTelephone()).orElse(null);
43	    }
44	
45	    /** The owner's name formatted as 'LastName, FirstName' from the stored names. */
46	    default String displayName(Owner owner) {
47	        return owner.getLastName() + ", " + owner.getFirstName();
48	    }
49	
50	    /** The upper-cased first letters of firstName and lastName, dot-separated with a
51	     *  trailing dot, e.g. 'J.S.'. */
52	    default String initials(Owner owner) {
53	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
54	                + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
55	    }
56	
57	    /** The membership number '&lt;customerCode&gt;-M&lt;YY&gt;', where YY is the last two digits of
58	     *  the registrationDate year (e.g. 'NSW-1A2B3C4D-M26'). Null when either source field is absent. */
59	    default String membershipNumber(Owner owner) {
60	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
61	            return null;
62	        }
63	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
64	    }
65	
66	    /** The Luhn check digit over the digits of the customerCode. Null when the customerCode
67	     *  is absent. */
68	    default Integer checkDigit(Owner owner) {
69	        return owner.getCustomerCode() == null ? null : Luhn.checkDigit(owner.getCustomerCode());
70	    }
71	
72	    /** The owner's locality: the REGION segment of its customerCode, which is the canonical region
73	     *  the code was built from. Falls back to deriving the region straight from the postcode and
74	     *  city when the customerCode is absent (so an owner without one still resolves a locality). */
75	    default String locality(Owner owner) {
76	        return owner.getCustomerCode() != null
77	                ? CustomerCode.region(owner.getCustomerCode())
78	                : OwnerRegion.of(owner.getPostcode(), owner.getCity());
79	    }
80	
81	    /** The owner's preferred contact method: 'EMAIL' when an email address is present,
82	     *  otherwise 'PHONE'. */
83	    default String contactPreference(Owner owner) {
84	        return owner.getEmail() != null && !owner.getEmail().isEmpty() ? "EMAIL" : "PHONE";
85	    }
86	
87	    /** The owner's derived duplicate-detection identity key: normalized telephone, email and
88	     *  household id joined by '|'. See {@link OwnerIdentity#key}. */
89	    default String identityKey(Owner owner) {
90	        return OwnerIdentity.key(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
91	    }
92	
93	    /** The owner's age band derived from its birthDate against its registrationDate, or null when
94	     *  either date is absent. See {@link AgeBand}. */
95	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
96	        if (owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
97	            return null;
98	        }
99	        return OwnerDto.AgeBandEnum.fromValue(AgeBand.of(owner.getBirthDate(), owner.getRegistrationDate()));
100	    }
101	
102	    Owner toOwner(OwnerDto ownerDto);
103	
104	    @Mapping(target = "id", ignore = true)
105	    @Mapping(target = "pets", ignore = true)
106	    Owner toOwner(OwnerFieldsDto ownerDto);
107	
108	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
109	
110	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
111	
112	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
113	        OwnerPageDto ownerPageDto = new OwnerPageDto();
114	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
115	        ownerPageDto.setPage(ownerPage.getNumber());
116	        ownerPageDto.setSize(ownerPage.getSize());
117	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
118	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
119	        return ownerPageDto;
120	    }
121	}
