3	/**
4	 * The canonical region an owner belongs to: derived from the {@link PostcodeRange postcode range}
5	 * first, falling back to the fixed {@link CityRegion city-to-region table} when the postcode is
6	 * absent or in no known range, and {@link CityRegion#UNKNOWN} when neither resolves a region.
7	 *
8	 * <p>This is the single source of an owner's region, used both to build the region segment of the
9	 * {@link CustomerCode customer code} and to report the owner's locality.
10	 */
11	public final class OwnerRegion {
12	
13	    private OwnerRegion() {
14	    }
15	
16	    /** The region for the given {@code postcode} (preferred) or {@code city} (fallback). */
17	    public static String of(String postcode, String city) {
18	        String byPostcode = PostcodeRange.regionForPostcode(postcode);
19	        return byPostcode != null ? byPostcode : CityRegion.locality(city);
20	    }
21	}
